import type { SourceLocation, VisualEnvelope } from '../protocol/envelope';
import type { ViewState } from '../state/view-state';

export const HOST_PROTOCOL_VERSION = 1 as const;
export type HostRequest =
  | { channel: 'ply-vis'; version: 1; type: 'ready' }
  | { channel: 'ply-vis'; version: 1; type: 'error'; message: string }
  | { channel: 'ply-vis'; version: 1; type: 'navigate'; source: SourceLocation }
  | { channel: 'ply-vis'; version: 1; type: 'persist-state'; state: ViewState }
  | { channel: 'ply-vis'; version: 1; type: 'request-artifact' }
  | { channel: 'ply-vis'; version: 1; type: 'explain'; code: string }
  | { channel: 'ply-vis'; version: 1; type: 'explain-prompt' }
  // "I drew this one." The host and the viewer validate separately, and
  // the host cannot otherwise tell whether what it sent arrived: it sent an
  // envelope the viewer refused, recorded it as displayed, and then opened
  // that project's files for source links in the drawing still on screen
  // from the previous one (external review, 2026-09-06).
  | { channel: 'ply-vis'; version: 1; type: 'artifact-accepted'; deliveryId: string };
export type HostResponse =
  | { channel: 'ply-vis'; version: 1; type: 'artifact'; envelope: VisualEnvelope; deliveryId: string }
  | { channel: 'ply-vis'; version: 1; type: 'restore-state'; state: ViewState }
  | { channel: 'ply-vis'; version: 1; type: 'capabilities'; explain: boolean; installedTool?: string | undefined }
  // The host has nothing to draw and wants to say why: no workspace root
  // picked, a run that would not load, a project switched away from.
  //
  // It needs its own type because `error` already exists in the *other*
  // direction (viewer to host, for a runtime failure the host should log).
  // The host was sending that one here, `isHostResponse` rejected it as it
  // should, and the old drawing stayed on screen with no explanation --
  // the reader looking at a picture of a run that is no longer the
  // selected one, and nothing saying so. Found by external review
  // 2026-09-06 with a controller-to-viewer test.
  | { channel: 'ply-vis'; version: 1; type: 'clear'; message: string };

export interface HostBridge { post(message: HostRequest): void }
export const windowHostBridge = (): HostBridge => ({ post: (message) => window.parent.postMessage(message, '*') });
function isViewState(value: unknown): value is ViewState {
  if (typeof value !== 'object' || value === null) return false;
  const state = value as Record<string, unknown>;
  const overlays = state.overlays as Record<string, unknown> | undefined;
  return typeof state.zoom === 'number' && Number.isFinite(state.zoom) && typeof state.panX === 'number' && Number.isFinite(state.panX) && typeof state.panY === 'number' && Number.isFinite(state.panY) && typeof overlays === 'object' && overlays !== null && typeof overlays.earned === 'boolean' && typeof overlays.gap === 'boolean' && typeof overlays.violation === 'boolean' && (state.detailsHidden === undefined || typeof state.detailsHidden === 'boolean') && (state.runId === undefined || typeof state.runId === 'string') && (state.selectedId === undefined || typeof state.selectedId === 'string') && (state.focusedId === undefined || typeof state.focusedId === 'string') && (state.hoverTooltips === undefined || typeof state.hoverTooltips === 'boolean') && (state.legendVisible === undefined || typeof state.legendVisible === 'boolean');
}
export function isHostResponse(value: unknown): value is HostResponse {
  if (typeof value !== 'object' || value === null) return false;
  const message = value as Record<string, unknown>;
  return message.channel === 'ply-vis' && message.version === 1 && (message.type === 'artifact' && 'envelope' in message && typeof message.deliveryId === 'string' || message.type === 'restore-state' && isViewState(message.state) || message.type === 'capabilities' && typeof message.explain === 'boolean' || message.type === 'clear' && typeof message.message === 'string');
}
